def solveSudoku(board):
    def is_valid(r, c, k):
        for i in range(9):
            if board[r][i] == k or board[i][c] == k:
                return False
            if board[3 * (r // 3) + i // 3][3 * (c // 3) + i % 3] == k:
                return False
        return True

    def backtrack():
        for r in range(9):
            for c in range(9):
                if board[r][c] == '.':
                    for k in '123456789':
                        if is_valid(r, c, k):
                            board[r][c] = k
                            if backtrack(): return True
                            board[r][c] = '.'
                    return False
        return True

    backtrack()
